#include "agent/eval/governance.hpp"

#include <algorithm>
#include <cmath>
#include <numeric>

namespace agent_framework::eval {
namespace {
using json=nlohmann::json;
json metadata_free(const DatasetManifest&v){json layers=json::array();for(const auto&l:v.layers)layers.push_back({{"layer",dataset_layer_name(l.layer)},{"case_ids",l.case_ids},{"case_digests",l.case_digests}});return{{"dataset_id",v.dataset_id},{"version",v.version},{"license",v.license},{"layers",layers},{"created_at",v.created_at}};}
std::string item(const HumanLabel&l){return l.case_id+":"+l.criterion_id;}
}
nlohmann::json encode(const DatasetManifest&v){return contracts::make_typed_contract(v.metadata,"agent.eval_dataset_manifest/v1",metadata_free(v));}
nlohmann::json encode(const HumanLabel&v){return contracts::make_typed_contract(v.metadata,"agent.eval_human_label/v1",{{"label_id",v.label_id},{"dataset_id",v.dataset_id},{"dataset_version",v.dataset_version},{"case_id",v.case_id},{"criterion_id",v.criterion_id},{"reviewer_id",v.reviewer_id},{"reviewer_role",v.reviewer_role},{"categorical_label",v.categorical_label},{"score",v.score},{"evidence_ids",v.evidence_ids},{"created_at",v.created_at}});}
nlohmann::json encode(const InterRaterBaseline&v){return{{"dataset_id",v.dataset_id},{"dataset_version",v.dataset_version},{"paired_items",v.paired_items},{"raw_agreement",v.raw_agreement},{"cohens_kappa",v.cohens_kappa},{"disputed_item_ids",v.disputed_item_ids},{"digest",v.digest}};}
nlohmann::json encode(const QuarantineDecision&v){return{{"case_id",v.case_id},{"quarantined",v.quarantined},{"reasons",v.reasons},{"digest",v.digest}};}
DatasetManifestValidation validate_manifest(const DatasetManifest&manifest,const DatasetRegistry&registry){DatasetManifestValidation out;std::set<DatasetLayer>layers;std::set<std::string>cases;if(manifest.dataset_id.empty()||manifest.version.empty()||manifest.license.empty())out.issues.push_back("manifest_identity_missing");for(const auto&layer:manifest.layers){if(!layers.insert(layer.layer).second)out.issues.push_back("duplicate_layer:"+dataset_layer_name(layer.layer));if(layer.case_ids.empty()||layer.case_ids.size()!=layer.case_digests.size())out.issues.push_back("invalid_layer_cases:"+dataset_layer_name(layer.layer));for(std::size_t i=0;i<layer.case_ids.size()&&i<layer.case_digests.size();++i){if(!cases.insert(layer.case_ids[i]).second)out.issues.push_back("duplicate_case:"+layer.case_ids[i]);auto found=registry.case_for_scoring(layer.case_ids[i]);if(!found)out.issues.push_back("case_missing:"+layer.case_ids[i]);else{const auto digest=encode(*found).at("canonical_digest").get<std::string>();if(found->dataset_version!=manifest.version)out.issues.push_back("case_version_mismatch:"+layer.case_ids[i]);if(digest!=layer.case_digests[i])out.issues.push_back("case_digest_mismatch:"+layer.case_ids[i]);}}}for(const auto layer:{DatasetLayer::Unit,DatasetLayer::Repository,DatasetLayer::Domain,DatasetLayer::Adversarial,DatasetLayer::Recovery,DatasetLayer::Live})if(!layers.count(layer))out.issues.push_back("layer_missing:"+dataset_layer_name(layer));out.digest=contracts::canonical_digest(metadata_free(manifest)).value_or("");out.valid=out.issues.empty()&&!out.digest.empty();return out;}
std::optional<InterRaterBaseline> calculate_inter_rater_baseline(const std::vector<HumanLabel>&labels,std::string*error){if(labels.empty()){if(error)*error="labels required";return std::nullopt;}const auto dataset=labels.front().dataset_id,version=labels.front().dataset_version;std::map<std::string,std::vector<const HumanLabel*>>by_item;std::set<std::string>reviewers,categories;for(const auto&label:labels){if(label.dataset_id!=dataset||label.dataset_version!=version||label.reviewer_id.empty()||label.categorical_label.empty()||!std::isfinite(label.score)){if(error)*error="inconsistent label set";return std::nullopt;}by_item[item(label)].push_back(&label);reviewers.insert(label.reviewer_id);categories.insert(label.categorical_label);}if(reviewers.size()!=2){if(error)*error="exactly two independent reviewers required";return std::nullopt;}std::uint64_t paired=0,agree=0;std::map<std::string,std::uint64_t>marginal;std::vector<std::string>disputed;for(const auto&[id,values]:by_item){std::map<std::string,const HumanLabel*>unique;for(const auto*value:values)if(!unique.emplace(value->reviewer_id,value).second){if(error)*error="duplicate reviewer label";return std::nullopt;}if(unique.size()!=2)continue;++paired;auto it=unique.begin();const auto a=it++->second->categorical_label,b=it->second->categorical_label;++marginal[a];++marginal[b];if(a==b)++agree;else disputed.push_back(id);}if(paired==0){if(error)*error="no paired labels";return std::nullopt;}const double observed=static_cast<double>(agree)/paired;double expected=0;for(const auto&[category,count]:marginal){const double p=static_cast<double>(count)/(2.0*paired);expected+=p*p;}const double kappa=std::abs(1.0-expected)<1e-12?1.0:(observed-expected)/(1.0-expected);InterRaterBaseline out{dataset,version,paired,observed,kappa,std::move(disputed),{}};out.digest=contracts::canonical_digest(encode(out)).value_or("");return out;}
QuarantineDecision evaluate_flakiness(const CaseHistory&history,const FlakyPolicy&policy){QuarantineDecision out;out.case_id=history.case_id;if(history.passed.size()<policy.minimum_runs)out.reasons.push_back("insufficient_runs");else{const auto failures=std::count(history.passed.begin(),history.passed.end(),false);const double rate=static_cast<double>(failures)/history.passed.size();if(rate>0&&rate<=policy.maximum_failure_rate)out.reasons.push_back("intermittent_failure");for(const auto&[metric,samples]:history.metric_samples){if(samples.size()<policy.minimum_runs)continue;const double mean=std::accumulate(samples.begin(),samples.end(),0.0)/samples.size();double variance=0;for(const auto value:samples)variance+=(value-mean)*(value-mean);variance/=samples.size();const double cv=std::abs(mean)<1e-12?(variance>0?INFINITY:0):std::sqrt(variance)/std::abs(mean);if(cv>policy.maximum_metric_coefficient_of_variation)out.reasons.push_back("metric_variance:"+metric);}}out.quarantined=std::find(out.reasons.begin(),out.reasons.end(),"intermittent_failure")!=out.reasons.end()||std::any_of(out.reasons.begin(),out.reasons.end(),[](const auto&r){return r.rfind("metric_variance:",0)==0;});auto basis=encode(out);basis.erase("digest");out.digest=contracts::canonical_digest(basis).value_or("");return out;}
}  // namespace agent_framework::eval
